"""Install an exact committed toolkit into a project and verify it offline."""
from __future__ import annotations

import argparse
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import shutil
import subprocess
import sys
import tempfile

SOURCE_PREFIX = "manim-pdfpc-derivations/scripts/derivation_toolkit"
VENDOR = Path("tools/vendor/manim_pdfpc/derivation_toolkit")
LOCK = Path("tools/derivation-toolkit.lock.json")
ENTRY = Path("tools/derivations.py")
BOOTSTRAP = '''#!/usr/bin/env python3
"""Generated by manim-pdfpc-derivations; update through its installer."""
from pathlib import Path
import sys

sys.dont_write_bytecode = True
project = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(project / "tools/vendor/manim_pdfpc"))
from derivation_toolkit.install import verify_installation
verify_installation(project)
from derivation_toolkit.cli import main
raise SystemExit(main(default_project=project))
'''


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _relative(value: str) -> Path:
    path = PurePosixPath(value)
    if path.is_absolute() or not path.parts or any(part in ("", ".", "..") for part in path.parts):
        raise ValueError(f"Invalid toolkit inventory path: {value}")
    return Path(*path.parts)


def _inventory(root: Path) -> dict[str, dict]:
    result = {}
    if not root.is_dir() or root.is_symlink():
        raise ValueError(f"Missing ordinary toolkit directory: {root}")
    for path in sorted(root.rglob("*")):
        if path.is_symlink():
            raise ValueError(f"Toolkit source cannot contain a symbolic link: {path}")
        if path.is_file():
            result[path.relative_to(root).as_posix()] = {
                "sha256": digest(path.read_bytes()),
                "mode": "755" if path.stat().st_mode & 0o111 else "644",
            }
    return result


def verify_installation(project: str | Path) -> dict:
    """Check every installed byte and mode without a skill checkout or network."""
    project = Path(project).expanduser().resolve()
    path = project / LOCK
    if not path.is_file() or path.is_symlink():
        raise ValueError(f"Missing ordinary toolkit lock file: {path}")
    lock = json.loads(path.read_text(encoding="utf-8"))
    if lock.get("version") != 1 or lock.get("source_path") != SOURCE_PREFIX:
        raise ValueError(f"Unsupported toolkit lock: {path}")
    expected = lock["files"]
    for name in expected:
        _relative(name)
    actual = _inventory(project / VENDOR)
    if actual != expected:
        missing = sorted(expected.keys() - actual.keys())
        extra = sorted(actual.keys() - expected.keys())
        changed = sorted(name for name in actual.keys() & expected.keys() if actual[name] != expected[name])
        raise ValueError("Installed toolkit differs from its lock. Preserve local edits and update the canonical skill; "
                         f"missing={missing}, extra={extra}, changed={changed}")
    entry = project / ENTRY
    if not entry.is_file() or entry.is_symlink() or digest(entry.read_bytes()) != lock["entry_sha256"]:
        raise ValueError(f"The generated toolkit entry point has local edits: {entry}")
    return lock


def _git(source: Path, *args: str) -> bytes:
    return subprocess.check_output(["git", "-C", str(source), *args], stderr=subprocess.PIPE)


def committed_files(source: Path, revision: str) -> tuple[str, str, dict[str, bytes], dict[str, dict]]:
    resolved = _git(source, "rev-parse", "--verify", revision + "^{commit}").decode().strip()
    if len(resolved) != 40:
        raise ValueError("A toolkit source must resolve to a full Git commit")
    try:
        repository = _git(source, "remote", "get-url", "origin").decode().strip()
    except subprocess.CalledProcessError:
        repository = str(source.resolve())
    files, inventory = {}, {}
    records = _git(source, "ls-tree", "-rz", "--full-tree", resolved, "--", SOURCE_PREFIX).split(b"\0")
    for record in records:
        if not record:
            continue
        heading, full_name = record.split(b"\t", 1)
        mode, kind, object_id = heading.decode().split()
        if kind != "blob" or mode not in ("100644", "100755"):
            raise ValueError("The toolkit transport requires regular files")
        relative = PurePosixPath(full_name.decode()).relative_to(SOURCE_PREFIX).as_posix()
        _relative(relative)
        contents = _git(source, "cat-file", "blob", object_id)
        files[relative] = contents
        inventory[relative] = {"sha256": digest(contents), "mode": mode[-3:]}
    if "__init__.py" not in files or "cli.py" not in files or "install.py" not in files:
        raise ValueError(f"The selected commit has no complete toolkit at {SOURCE_PREFIX}")
    return resolved, repository, files, inventory


def install(project: str | Path, source: str | Path, revision: str) -> dict:
    """Replace only a verified prior installation; unrelated project files stay owned by the project."""
    project, source = Path(project).expanduser().resolve(), Path(source).expanduser().resolve()
    if not project.is_dir():
        raise ValueError(f"The target project does not exist: {project}")
    target, lock_path, entry = project / VENDOR, project / LOCK, project / ENTRY
    if lock_path.exists() or lock_path.is_symlink():
        verify_installation(project)
    elif target.exists() or target.is_symlink() or entry.exists() or entry.is_symlink():
        raise ValueError("Preserving existing unowned toolkit or entry point; select an empty installation location")
    resolved, repository, files, inventory = committed_files(source, revision)
    bootstrap = BOOTSTRAP.encode()
    lock = {"version": 1, "repository": repository, "revision": resolved,
            "source_path": SOURCE_PREFIX, "files": inventory,
            "entry_sha256": digest(bootstrap)}
    target.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix=".toolkit-install-", dir=target.parent) as temporary:
        staging = Path(temporary) / "package"
        staging.mkdir()
        for name, contents in files.items():
            path = staging / _relative(name)
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(contents)
            path.chmod(int(inventory[name]["mode"], 8))
        if _inventory(staging) != inventory:
            raise ValueError("Staged toolkit failed its source inventory check")
        backup = Path(temporary) / "previous"
        metadata = {}
        for path in (entry, lock_path):
            metadata[path] = (path.read_bytes(), path.stat().st_mode & 0o777) if path.exists() else None
        if target.exists():
            os.replace(target, backup)
        try:
            os.replace(staging, target)
            entry.parent.mkdir(parents=True, exist_ok=True)
            entry.write_bytes(bootstrap)
            entry.chmod(0o755)
            lock_path.write_text(json.dumps(lock, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            verify_installation(project)
        except BaseException:
            if target.exists():
                shutil.rmtree(target)
            if backup.exists():
                os.replace(backup, target)
            for path, previous in metadata.items():
                if previous is None:
                    path.unlink(missing_ok=True)
                else:
                    path.write_bytes(previous[0])
                    path.chmod(previous[1])
            raise
    return lock


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--project", type=Path, required=True)
    parser.add_argument("--source", type=Path, help="Local canonical claude-skills Git checkout")
    parser.add_argument("--revision", help="Explicit source commit; installation never reads uncommitted skill files")
    parser.add_argument("--check", action="store_true", help="Verify the complete installed inventory offline")
    args = parser.parse_args(argv)
    if args.check:
        lock = verify_installation(args.project)
        if args.source:
            _, _, _, canonical = committed_files(args.source, lock["revision"])
            if canonical != lock["files"]:
                raise ValueError("The installed lock differs from its committed canonical source")
    else:
        if args.source is None or args.revision is None:
            parser.error("installation requires --source and --revision")
        lock = install(args.project, args.source, args.revision)
    print(json.dumps({"project": str(args.project.resolve()), "revision": lock["revision"],
                      "files": len(lock["files"]), "checked": True}, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
